  const model = this.requireModel();
  const { session } = await createAgentSession({
    cwd: this.cwd,
    modelRuntime: this.runtime,
    model,
    noTools: 'all',
    sessionManager: SessionManager.inMemory(this.cwd),
  });
  try {
    let out = '';
    let streamError: string | undefined;
    const unsub = session.subscribe((e) => {
      if (e.type === 'message_update') {
        const ev = e.assistantMessageEvent;
        if (ev.type === 'text_delta') out += ev.delta;
        else if (ev.type === 'error') streamError = ev.error?.errorMessage ?? '模型返回错误';
      }
    });
    await session.prompt(buildSingleTurn(systemPrompt, userPrompt));
    unsub();
    const err = streamError ?? lastMessageError(session);
    if (err) throw new Error(`模型调用失败：${err}`);
    const text = out.trim();
    if (!text) throw new Error('模型返回空内容（可能是 API Key 无效或额度不足）');
    return text;
  } finally {
    session.dispose();
  }
}

